import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Main {
    // Prefix sums: prefix[i] = sum of nums[0..i-1], so prefix has n+1 entries.
    static long[] buildPrefix(int[] nums) {
        long[] prefix = new long[nums.length + 1];
        for (int i = 0; i < nums.length; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }
        return prefix;
    }

    // Sum of nums[l..r] inclusive in O(1).
    static long rangeSum(long[] prefix, int l, int r) {
        return prefix[r + 1] - prefix[l];
    }

    // Count subarrays whose sum equals k (works with negatives).
    static int subarraySum(int[] nums, int k, boolean trace) {
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, 1);                       // the empty prefix
        int running = 0, count = 0;
        for (int i = 0; i < nums.length; i++) {
            running += nums[i];
            int need = running - k;
            int add = seen.getOrDefault(need, 0);
            count += add;
            seen.merge(running, 1, Integer::sum);
            if (trace) {
                System.out.printf("i=%d x=%2d running=%2d need=%2d add=%d count=%d map=%s%n",
                        i, nums[i], running, need, add, count, seen);
            }
        }
        return count;
    }

    static int subarraySumBrute(int[] nums, int k) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            int sum = 0;
            for (int j = i; j < nums.length; j++) {
                sum += nums[j];
                if (sum == k) count++;
            }
        }
        return count;
    }

    // Difference array: add 'delta' to every element in [l, r] in O(1).
    static int[] applyUpdates(int n, int[][] updates) {
        int[] diff = new int[n + 1];
        for (int[] u : updates) {
            diff[u[0]] += u[2];
            diff[u[1] + 1] -= u[2];
        }
        int[] result = new int[n];
        int running = 0;
        for (int i = 0; i < n; i++) {
            running += diff[i];
            result[i] = running;
        }
        System.out.println("diff   = " + Arrays.toString(diff));
        return result;
    }

    // 2D prefix sums: p[i][j] = sum of matrix[0..i-1][0..j-1].
    static int[][] build2D(int[][] m) {
        int[][] p = new int[m.length + 1][m[0].length + 1];
        for (int i = 0; i < m.length; i++) {
            for (int j = 0; j < m[0].length; j++) {
                p[i + 1][j + 1] = m[i][j] + p[i][j + 1] + p[i + 1][j] - p[i][j];
            }
        }
        return p;
    }

    static int region(int[][] p, int r1, int c1, int r2, int c2) {
        return p[r2 + 1][c2 + 1] - p[r1][c2 + 1] - p[r2 + 1][c1] + p[r1][c1];
    }

    public static void main(String[] args) {
        int[] nums = {3, 1, 4, 1, 5, 9, 2, 6};
        long[] prefix = buildPrefix(nums);
        System.out.println("prefix = " + Arrays.toString(prefix));
        System.out.println("sum[2..5] = " + rangeSum(prefix, 2, 5));
        System.out.println("sum[0..7] = " + rangeSum(prefix, 0, 7));

        int[] a = {1, 2, 3, -1, 2};
        System.out.println("-- subarray sum equals 3, trace --");
        System.out.println("answer = " + subarraySum(a, 3, true));
        System.out.println("brute  = " + subarraySumBrute(a, 3));

        System.out.println("-- difference array --");
        int[][] updates = {{1, 3, 2}, {2, 4, 3}, {0, 1, 1}};
        System.out.println("result = " + Arrays.toString(applyUpdates(5, updates)));

        System.out.println("-- 2D prefix --");
        int[][] m = {{3, 0, 1}, {5, 6, 3}, {1, 2, 0}};
        int[][] p = build2D(m);
        for (int[] row : p) System.out.println(Arrays.toString(row));
        System.out.println("region(1,1)-(2,2) = " + region(p, 1, 1, 2, 2));
        System.out.println("region(0,0)-(1,2) = " + region(p, 0, 0, 1, 2));
    }
}

