import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main {
    // Opposite ends: sorted array, find a pair with the given sum. Returns indices or {-1,-1}.
    static int[] twoSumSorted(int[] a, int target, boolean trace) {
        int lo = 0, hi = a.length - 1, step = 1;
        while (lo < hi) {
            int sum = a[lo] + a[hi];
            if (trace) {
                System.out.printf("step %d lo=%d hi=%d a[lo]=%d a[hi]=%d sum=%d%n",
                        step++, lo, hi, a[lo], a[hi], sum);
            }
            if (sum == target) return new int[]{lo, hi};
            if (sum < target) lo++; else hi--;
        }
        return new int[]{-1, -1};
    }

    // Same direction: write pointer 'w' trails read pointer 'r'.
    static int removeDuplicates(int[] a) {
        if (a.length == 0) return 0;
        int w = 1;
        for (int r = 1; r < a.length; r++) {
            if (a[r] != a[w - 1]) a[w++] = a[r];
        }
        return w;
    }

    static void moveZeroes(int[] a) {
        int w = 0;
        for (int r = 0; r < a.length; r++) {
            if (a[r] != 0) {
                int t = a[w]; a[w] = a[r]; a[r] = t;
                w++;
            }
        }
    }

    // 3Sum: sort, fix i, two pointers on the rest, skip duplicates.
    static List<List<Integer>> threeSum(int[] nums) {
        int[] a = nums.clone();
        Arrays.sort(a);
        List<List<Integer>> out = new ArrayList<>();
        for (int i = 0; i < a.length - 2; i++) {
            if (a[i] > 0) break;
            if (i > 0 && a[i] == a[i - 1]) continue;
            int lo = i + 1, hi = a.length - 1;
            while (lo < hi) {
                int sum = a[i] + a[lo] + a[hi];
                if (sum < 0) lo++;
                else if (sum > 0) hi--;
                else {
                    out.add(List.of(a[i], a[lo], a[hi]));
                    lo++; hi--;
                    while (lo < hi && a[lo] == a[lo - 1]) lo++;
                    while (lo < hi && a[hi] == a[hi + 1]) hi--;
                }
            }
        }
        return out;
    }

    static int maxArea(int[] h, boolean trace) {
        int lo = 0, hi = h.length - 1, best = 0, step = 1;
        while (lo < hi) {
            int area = Math.min(h[lo], h[hi]) * (hi - lo);
            best = Math.max(best, area);
            if (trace) {
                System.out.printf("step %d lo=%d hi=%d h[lo]=%d h[hi]=%d area=%2d best=%2d%n",
                        step++, lo, hi, h[lo], h[hi], area, best);
            }
            if (h[lo] < h[hi]) lo++; else hi--;
        }
        return best;
    }

    static int maxAreaBrute(int[] h) {
        int best = 0;
        for (int i = 0; i < h.length; i++)
            for (int j = i + 1; j < h.length; j++)
                best = Math.max(best, Math.min(h[i], h[j]) * (j - i));
        return best;
    }

    static boolean isPalindrome(String s) {
        int lo = 0, hi = s.length() - 1;
        while (lo < hi) {
            while (lo < hi && !Character.isLetterOrDigit(s.charAt(lo))) lo++;
            while (lo < hi && !Character.isLetterOrDigit(s.charAt(hi))) hi--;
            if (Character.toLowerCase(s.charAt(lo)) != Character.toLowerCase(s.charAt(hi))) {
                return false;
            }
            lo++; hi--;
        }
        return true;
    }

    public static void main(String[] args) {
        int[] sorted = {1, 3, 4, 6, 8, 11};
        System.out.println("-- two sum on sorted, target 10 --");
        System.out.println(Arrays.toString(twoSumSorted(sorted, 10, true)));

        int[] heights = {1, 8, 6, 2, 5, 4, 8, 3, 7};
        System.out.println("-- container with most water --");
        System.out.println("answer = " + maxArea(heights, true));
        System.out.println("brute  = " + maxAreaBrute(heights));

        int[] d = {0, 0, 1, 1, 1, 2, 2, 3};
        int len = removeDuplicates(d);
        System.out.println("unique length " + len + " -> "
                + Arrays.toString(Arrays.copyOf(d, len)));
        int[] z = {0, 1, 0, 3, 12};
        moveZeroes(z);
        System.out.println("moveZeroes -> " + Arrays.toString(z));
        System.out.println("3sum -> " + threeSum(new int[]{-1, 0, 1, 2, -1, -4}));
        System.out.println("3sum all zeros -> " + threeSum(new int[]{0, 0, 0, 0}));
        System.out.println(isPalindrome("A man, a plan, a canal: Panama"));
        System.out.println(isPalindrome("race a car"));
    }
}

