import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main {
    // Maximum sum of any k consecutive elements.
    static int maxSumWindow(int[] a, int k, boolean trace) {
        int window = 0;
        for (int i = 0; i < k; i++) window += a[i];
        int best = window;
        if (trace) System.out.printf("init window [0..%d] sum=%d best=%d%n", k - 1, window, best);
        for (int right = k; right < a.length; right++) {
            int left = right - k;                 // element leaving the window
            window += a[right] - a[left];
            best = Math.max(best, window);
            if (trace) {
                System.out.printf("add a[%d]=%d drop a[%d]=%d -> window [%d..%d] sum=%d best=%d%n",
                        right, a[right], left, a[left], left + 1, right, window, best);
            }
        }
        return best;
    }

    static int maxSumBrute(int[] a, int k) {
        int best = Integer.MIN_VALUE;
        for (int i = 0; i + k <= a.length; i++) {
            int sum = 0;
            for (int j = i; j < i + k; j++) sum += a[j];
            best = Math.max(best, sum);
        }
        return best;
    }

    static double maxAverage(int[] a, int k) {
        long window = 0;
        for (int i = 0; i < k; i++) window += a[i];
        long best = window;
        for (int i = k; i < a.length; i++) {
            window += a[i] - a[i - k];
            best = Math.max(best, window);
        }
        return (double) best / k;
    }

    // Fixed window over a string: start indices of anagrams of p inside s.
    static List<Integer> findAnagrams(String s, String p) {
        List<Integer> out = new ArrayList<>();
        if (p.length() > s.length()) return out;
        int[] need = new int[26], have = new int[26];
        for (char c : p.toCharArray()) need[c - 'a']++;
        for (int i = 0; i < s.length(); i++) {
            have[s.charAt(i) - 'a']++;
            if (i >= p.length()) have[s.charAt(i - p.length()) - 'a']--;
            if (i >= p.length() - 1 && Arrays.equals(need, have)) out.add(i - p.length() + 1);
        }
        return out;
    }

    // Max vowels in any substring of length k.
    static int maxVowels(String s, int k) {
        int cur = 0, best = 0;
        for (int i = 0; i < s.length(); i++) {
            if ("aeiou".indexOf(s.charAt(i)) >= 0) cur++;
            if (i >= k && "aeiou".indexOf(s.charAt(i - k)) >= 0) cur--;
            best = Math.max(best, cur);
        }
        return best;
    }

    public static void main(String[] args) {
        int[] a = {2, 1, 5, 1, 3, 2};
        System.out.println("-- max sum of 3 consecutive --");
        System.out.println("answer = " + maxSumWindow(a, 3, true));
        System.out.println("brute  = " + maxSumBrute(a, 3));
        System.out.println("max average k=4: " + maxAverage(new int[]{1, 12, -5, -6, 50, 3}, 4));
        System.out.println("anagrams: " + findAnagrams("cbaebabacd", "abc"));
        System.out.println("anagrams: " + findAnagrams("abab", "ab"));
        System.out.println("vowels: " + maxVowels("abciiidef", 3));
        int[] big = {Integer.MAX_VALUE, Integer.MAX_VALUE, Integer.MAX_VALUE};
        int bad = 0;
        for (int x : big) bad += x;
        long ok = 0;
        for (int x : big) ok += x;
        System.out.println("int sum = " + bad + ", long sum = " + ok);
    }
}

