import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class Main {
    // Longest substring with all distinct characters (set version, with trace).
    static int lengthOfLongest(String s, boolean trace) {
        Set<Character> inWindow = new HashSet<>();
        int left = 0, best = 0, step = 1;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            while (inWindow.contains(c)) {
                inWindow.remove(s.charAt(left));
                left++;
            }
            inWindow.add(c);
            best = Math.max(best, right - left + 1);
            if (trace) {
                String win = s.substring(left, right + 1);
                System.out.printf("step %d right=%d char=%s left=%d window=%s len=%d best=%d%n",
                        step++, right, c, left, win, right - left + 1, best);
            }
        }
        return best;
    }

    // Same problem with a last-seen map: the left edge jumps.
    static int lengthOfLongestJump(String s) {
        Map<Character, Integer> last = new HashMap<>();
        int left = 0, best = 0;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            if (last.containsKey(c)) left = Math.max(left, last.get(c) + 1);
            last.put(c, right);
            best = Math.max(best, right - left + 1);
        }
        return best;
    }

    static int lengthOfLongestBrute(String s) {
        int best = 0;
        for (int i = 0; i < s.length(); i++) {
            Set<Character> seen = new HashSet<>();
            for (int j = i; j < s.length(); j++) {
                if (!seen.add(s.charAt(j))) break;
                best = Math.max(best, j - i + 1);
            }
        }
        return best;
    }

    // Longest substring with at most k distinct characters.
    static int longestKDistinct(String s, int k) {
        Map<Character, Integer> count = new HashMap<>();
        int left = 0, best = 0;
        for (int right = 0; right < s.length(); right++) {
            count.merge(s.charAt(right), 1, Integer::sum);
            while (count.size() > k) {
                char out = s.charAt(left++);
                if (count.merge(out, -1, Integer::sum) == 0) count.remove(out);
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }

    // Longest repeating character replacement.
    static int characterReplacement(String s, int k) {
        int[] count = new int[26];
        int left = 0, maxFreq = 0, best = 0;
        for (int right = 0; right < s.length(); right++) {
            maxFreq = Math.max(maxFreq, ++count[s.charAt(right) - 'A']);
            while (right - left + 1 - maxFreq > k) {
                count[s.charAt(left++) - 'A']--;
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }

    // Minimum window substring: smallest window of s containing all chars of t.
    static String minWindow(String s, String t, boolean trace) {
        int[] need = new int[128];
        for (char c : t.toCharArray()) need[c]++;
        int missing = t.length();
        int left = 0, bestStart = 0, bestLen = Integer.MAX_VALUE;
        for (int right = 0; right < s.length(); right++) {
            if (need[s.charAt(right)]-- > 0) missing--;
            while (missing == 0) {
                if (right - left + 1 < bestLen) {
                    bestLen = right - left + 1;
                    bestStart = left;
                    if (trace) System.out.println("  valid window [" + left + ".." + right + "] = "
                            + s.substring(left, right + 1));
                }
                if (++need[s.charAt(left++)] > 0) missing++;
            }
        }
        return bestLen == Integer.MAX_VALUE ? "" : s.substring(bestStart, bestStart + bestLen);
    }

    // Subarrays with sum <= goal (non-negative array). Exactly g = atMost(g) - atMost(g-1).
    static int atMost(int[] a, int goal) {
        if (goal < 0) return 0;
        int left = 0, sum = 0, count = 0;
        for (int right = 0; right < a.length; right++) {
            sum += a[right];
            while (sum > goal) sum -= a[left++];
            count += right - left + 1;
        }
        return count;
    }

    public static void main(String[] args) {
        System.out.println("-- longest substring without repeats: abcabcbb --");
        System.out.println("answer = " + lengthOfLongest("abcabcbb", true));
        System.out.println("jump   = " + lengthOfLongestJump("abcabcbb"));
        System.out.println("brute  = " + lengthOfLongestBrute("abcabcbb"));
        System.out.println("abba -> " + lengthOfLongest("abba", false) + ", jump "
                + lengthOfLongestJump("abba"));
        System.out.println("at most 2 distinct in eceba: " + longestKDistinct("eceba", 2));
        System.out.println("replacement AABABBA k=1: " + characterReplacement("AABABBA", 1));
        System.out.println("-- minimum window ADOBECODEBANC / ABC --");
        System.out.println("answer = " + minWindow("ADOBECODEBANC", "ABC", true));
        int[] bin = {1, 0, 1, 0, 1};
        System.out.println("exactly 2: " + (atMost(bin, 2) - atMost(bin, 1)));
    }
}

