import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class Main {
    static int[] twoSum(int[] nums, int target, boolean trace) {
        Map<Integer, Integer> indexOf = new HashMap<>();   // value -> index
        for (int i = 0; i < nums.length; i++) {
            int need = target - nums[i];
            if (trace) System.out.printf("i=%d x=%d need=%d map=%s%n", i, nums[i], need, indexOf);
            Integer j = indexOf.get(need);
            if (j != null) return new int[]{j, i};
            indexOf.put(nums[i], i);
        }
        return new int[]{-1, -1};
    }

    static boolean isAnagram(String a, String b) {
        if (a.length() != b.length()) return false;
        int[] count = new int[26];
        for (int i = 0; i < a.length(); i++) {
            count[a.charAt(i) - 'a']++;
            count[b.charAt(i) - 'a']--;
        }
        for (int c : count) if (c != 0) return false;
        return true;
    }

    static List<List<String>> groupAnagrams(String[] words) {
        Map<String, List<String>> groups = new HashMap<>();
        for (String w : words) {
            char[] cs = w.toCharArray();
            Arrays.sort(cs);
            groups.computeIfAbsent(new String(cs), k -> new ArrayList<>()).add(w);
        }
        return new ArrayList<>(groups.values());
    }

    // Top k frequent by bucket sort: bucket[f] holds the values that occur f times.
    static List<Integer> topK(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int x : nums) freq.merge(x, 1, Integer::sum);
        List<List<Integer>> bucket = new ArrayList<>();
        for (int i = 0; i <= nums.length; i++) bucket.add(new ArrayList<>());
        for (var e : freq.entrySet()) bucket.get(e.getValue()).add(e.getKey());
        List<Integer> out = new ArrayList<>();
        for (int f = nums.length; f >= 1 && out.size() < k; f--) {
            for (int v : bucket.get(f)) {
                if (out.size() < k) out.add(v);
            }
        }
        return out;
    }

    static int longestConsecutive(int[] nums, boolean trace) {
        Set<Integer> set = new HashSet<>();
        for (int x : nums) set.add(x);
        int best = 0;
        for (int x : nums) {
            if (set.contains(x - 1)) {
                if (trace) {
                    System.out.println("x=" + x + ": " + (x - 1) + " exists, not a start, skip");
                }
                continue;
            }
            int cur = x, len = 1;
            while (set.contains(cur + 1)) { cur++; len++; }
            best = Math.max(best, len);
            if (trace) {
                System.out.println("x=" + x + ": start, run " + x + ".." + cur
                        + " length " + len + ", best=" + best);
            }
        }
        return best;
    }

    static boolean hasDuplicate(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        for (int x : nums) if (!seen.add(x)) return true;
        return false;
    }

    public static void main(String[] args) {
        System.out.println("-- two sum: [2, 11, 7, 15, 3], target 9 --");
        System.out.println(Arrays.toString(twoSum(new int[]{2, 11, 7, 15, 3}, 9, true)));
        System.out.println(isAnagram("listen", "silent") + " " + isAnagram("rat", "car"));
        System.out.println(groupAnagrams(new String[]{"eat", "tea", "tan", "ate", "nat", "bat"}));
        System.out.println("top2: " + topK(new int[]{1, 1, 1, 2, 2, 3}, 2));
        System.out.println("-- longest consecutive: [100, 4, 200, 1, 3, 2] --");
        System.out.println("answer = " + longestConsecutive(new int[]{100, 4, 200, 1, 3, 2}, true));
        System.out.println("duplicate? " + hasDuplicate(new int[]{1, 2, 3, 1}));

        Integer a = 127, b = 127, c = 1000, d = 1000;
        System.out.println("127 == 127 : " + (a == b) + ", 1000 == 1000 : " + (c == d)
                + ", equals : " + c.equals(d));
        Map<Integer, Integer> m = new HashMap<>();
        m.put(1000, 5);
        m.put(1000, 7);
        System.out.println("map = " + m + " size " + m.size());
    }
}

