import java.util.Arrays;

public class Main {
    // first index i with a[i] >= target (a.length if none)
    static int lowerBound(int[] a, int target) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] >= target) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    // first index i with a[i] > target
    static int upperBound(int[] a, int target) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] > target) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    static int[] firstLast(int[] a, int target) {
        int first = lowerBound(a, target);
        if (first == a.length || a[first] != target) return new int[] {-1, -1};
        return new int[] {first, upperBound(a, target) - 1};
    }

    static int searchRotated(int[] a, int target) {
        int lo = 0, hi = a.length - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] == target) return mid;
            if (a[lo] <= a[mid]) {                    // left half sorted
                if (a[lo] <= target && target < a[mid]) hi = mid - 1;
                else lo = mid + 1;
            } else {                                  // right half sorted
                if (a[mid] < target && target <= a[hi]) lo = mid + 1;
                else hi = mid - 1;
            }
        }
        return -1;
    }

    static int findMin(int[] a) {
        int lo = 0, hi = a.length - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] > a[hi]) lo = mid + 1;
            else hi = mid;
        }
        return a[lo];
    }

    static int findPeak(int[] a) {
        int lo = 0, hi = a.length - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] < a[mid + 1]) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static boolean searchMatrix(int[][] m, int target) {
        int rows = m.length, cols = m[0].length;
        int lo = 0, hi = rows * cols - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            int v = m[mid / cols][mid % cols];
            if (v == target) return true;
            if (v < target) lo = mid + 1;
            else hi = mid - 1;
        }
        return false;
    }

    public static void main(String[] args) {
        int[] a = {1, 2, 4, 4, 4, 7, 9};
        System.out.println("lowerBound(4) = " + lowerBound(a, 4));
        System.out.println("upperBound(4) = " + upperBound(a, 4));
        System.out.println("lowerBound(5) = " + lowerBound(a, 5));
        System.out.println("lowerBound(10) = " + lowerBound(a, 10));
        System.out.println("firstLast(4) = " + Arrays.toString(firstLast(a, 4)));
        System.out.println("firstLast(5) = " + Arrays.toString(firstLast(a, 5)));
        int[] r = {4, 5, 6, 7, 0, 1, 2};
        System.out.println("rotated search 0 -> " + searchRotated(r, 0));
        System.out.println("rotated search 3 -> " + searchRotated(r, 3));
        System.out.println("rotated min -> " + findMin(r));
        System.out.println("peak index -> " + findPeak(new int[] {1, 3, 5, 4, 2}));
        int[][] m = {{1, 3, 5, 7}, {10, 11, 16, 20}, {23, 30, 34, 60}};
        System.out.println("matrix has 16 -> " + searchMatrix(m, 16));
        System.out.println("matrix has 13 -> " + searchMatrix(m, 13));
        System.out.println("Arrays.binarySearch(a, 4) = " + Arrays.binarySearch(a, 4));
