static int kokoSpeed(int[] piles, int h) {
    int max = Arrays.stream(piles).max().getAsInt();
    return firstTrue(1, max, k -> {
        long hours = 0;
        for (int p : piles) hours += (p + k - 1) / k;      // ceil(p / k)
        return hours <= h;
    });
}

static int shipCapacity(int[] w, int days) {
    int lo = Arrays.stream(w).max().getAsInt();
    int hi = Arrays.stream(w).sum();
    return firstTrue(lo, hi, cap -> {
        int used = 1, load = 0;
        for (int x : w) {
            if (load + x > cap) { used++; load = 0; }
            load += x;
        }
        return used <= days;
    });
}

static int splitArray(int[] nums, int k) {
    int lo = Arrays.stream(nums).max().getAsInt();
    int hi = Arrays.stream(nums).sum();
    return firstTrue(lo, hi, limit -> {
        int parts = 1, sum = 0;
        for (int x : nums) {
            if (sum + x > limit) { parts++; sum = 0; }
            sum += x;
        }
        return parts <= k;
    });
}

static int minDaysBouquets(int[] bloom, int m, int k) {
    if ((long) m * k > bloom.length) return -1;
    int lo = Arrays.stream(bloom).min().getAsInt();
    int hi = Arrays.stream(bloom).max().getAsInt();
    return firstTrue(lo, hi, day -> {
        int made = 0, run = 0;
        for (int b : bloom) {
            if (b <= day) { if (++run == k) { made++; run = 0; } }
            else run = 0;
        }
        return made >= m;
    });
}

static int isqrt(int x) {            // largest r with r*r <= x
    int lo = 0, hi = Math.min(x, 46340);
    while (lo < hi) {
        int mid = lo + (hi - lo + 1) / 2;          // upper mid: avoids infinite loop
        if ((long) mid * mid <= x) lo = mid;
        else hi = mid - 1;
    }
    return lo;
}

