import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main {
    static int[][] merge(int[][] intervals) {
        int[][] a = intervals.clone();
        Arrays.sort(a, (x, y) -> Integer.compare(x[0], y[0]));
        List<int[]> out = new ArrayList<>();
        int[] cur = a[0].clone();
        for (int i = 1; i < a.length; i++) {
            if (a[i][0] <= cur[1]) cur[1] = Math.max(cur[1], a[i][1]);   // overlap: extend
            else { out.add(cur); cur = a[i].clone(); }                   // gap: close current
        }
        out.add(cur);
        return out.toArray(new int[0][]);
    }

    static int[][] insert(int[][] sorted, int[] nw) {
        List<int[]> out = new ArrayList<>();
        int i = 0, n = sorted.length;
        while (i < n && sorted[i][1] < nw[0]) out.add(sorted[i++]);          // entirely before
        int[] cur = nw.clone();
        while (i < n && sorted[i][0] <= cur[1]) {                            // overlapping
            cur[0] = Math.min(cur[0], sorted[i][0]);
            cur[1] = Math.max(cur[1], sorted[i][1]);
            i++;
        }
        out.add(cur);
        while (i < n) out.add(sorted[i++]);                                  // entirely after
        return out.toArray(new int[0][]);
    }

    // minimum number of rooms = maximum number of overlapping meetings
    static int minRooms(int[][] meetings) {
        int n = meetings.length;
        int[] starts = new int[n], ends = new int[n];
        for (int i = 0; i < n; i++) { starts[i] = meetings[i][0]; ends[i] = meetings[i][1]; }
        Arrays.sort(starts);
        Arrays.sort(ends);
        int rooms = 0, best = 0, j = 0;
        for (int i = 0; i < n; i++) {
            while (ends[j] <= starts[i]) { j++; rooms--; }     // a meeting finished: free a room
            rooms++;
            best = Math.max(best, rooms);
        }
        return best;
    }

    // fewest intervals to remove so the rest do not overlap: keep earliest finishing ones
    static int eraseOverlap(int[][] intervals) {
        int[][] a = intervals.clone();
        Arrays.sort(a, (x, y) -> Integer.compare(x[1], y[1]));
        int kept = 0, end = Integer.MIN_VALUE;
        for (int[] iv : a) {
            if (iv[0] >= end) { kept++; end = iv[1]; }
        }
        return a.length - kept;
    }

    static int[][] intersect(int[][] A, int[][] B) {
        List<int[]> out = new ArrayList<>();
        int i = 0, j = 0;
        while (i < A.length && j < B.length) {
            int lo = Math.max(A[i][0], B[j][0]);
            int hi = Math.min(A[i][1], B[j][1]);
            if (lo <= hi) out.add(new int[] {lo, hi});
            if (A[i][1] < B[j][1]) i++; else j++;                 // drop the one that ends first
        }
        return out.toArray(new int[0][]);
    }

    static boolean carPooling(int[][] trips, int capacity) {      // trip = {people, from, to}
        int[] delta = new int[1001];
        for (int[] t : trips) { delta[t[1]] += t[0]; delta[t[2]] -= t[0]; }
        int load = 0;
        for (int d : delta) { load += d; if (load > capacity) return false; }
        return true;
    }

    public static void main(String[] args) {
        System.out.println(Arrays.deepToString(
            merge(new int[][] {{1,3},{8,10},{2,6},{15,18},{17,20}})));
        System.out.println(Arrays.deepToString(merge(new int[][] {{1,4},{4,5}})));
        System.out.println(Arrays.deepToString(
            insert(new int[][] {{1,2},{3,5},{6,7},{8,10},{12,16}}, new int[] {4, 8})));
        System.out.println("rooms = " + minRooms(new int[][] {{0,30},{5,10},{15,20}}));
        System.out.println("rooms = " + minRooms(new int[][] {{7,10},{2,4}}));
        System.out.println("remove = " + eraseOverlap(new int[][] {{1,2},{2,3},{3,4},{1,3}}));
        System.out.println(Arrays.deepToString(intersect(new int[][] {{0,2},{5,10},{13,23},{24,25}},
            new int[][] {{1,5},{8,12},{15,24},{25,26}})));
        System.out.println("carPooling = " + carPooling(new int[][] {{2,1,5},{3,3,7}}, 4)
            + ", " + carPooling(new int[][] {{2,1,5},{3,5,7}}, 3));
        Integer[] nums = {3, 30, 34, 5, 9};
        Arrays.sort(nums, (x, y) -> (y.toString() + x).compareTo(x.toString() + y));
        System.out.println("largest number: "
            + String.join("", Arrays.stream(nums).map(String::valueOf).toList()));
    }
}

