import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main {
    static int maxSubarray(int[] a) {
        int best = a[0], cur = a[0];
        for (int i = 1; i < a.length; i++) {
            cur = Math.max(a[i], cur + a[i]);     // extend the run or restart here
            best = Math.max(best, cur);
        }
        return best;
    }

    static int maxProfit(int[] prices) {
        int minSoFar = Integer.MAX_VALUE, best = 0;
        for (int p : prices) {
            minSoFar = Math.min(minSoFar, p);
            best = Math.max(best, p - minSoFar);
        }
        return best;
    }

    static int maxProfitMany(int[] prices) {
        int total = 0;
        for (int i = 1; i < prices.length; i++)
            if (prices[i] > prices[i - 1]) total += prices[i] - prices[i - 1];
        return total;
    }

    static int[] productExceptSelf(int[] a) {
        int n = a.length;
        int[] out = new int[n];
        out[0] = 1;
        for (int i = 1; i < n; i++) out[i] = out[i - 1] * a[i - 1];   // product of all to the left
        int right = 1;
        for (int i = n - 1; i >= 0; i--) { out[i] *= right; right *= a[i]; }
    return out;
}

static void sortColors(int[] a) {                // Dutch national flag
    int lo = 0, mid = 0, hi = a.length - 1;
    while (mid <= hi) {
        if (a[mid] == 0) swap(a, lo++, mid++);
        else if (a[mid] == 2) swap(a, mid, hi--);   // do not advance mid: new value unseen
        else mid++;
    }
}

static void swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }

static int firstMissingPositive(int[] a) {       // cyclic sort: value v belongs at index v - 1
    int n = a.length;
    for (int i = 0; i < n; i++) {
        while (a[i] >= 1 && a[i] <= n && a[a[i] - 1] != a[i]) swap(a, i, a[i] - 1);
    }
    for (int i = 0; i < n; i++) if (a[i] != i + 1) return i + 1;
    return n + 1;
}

static void rotate(int[] a, int k) {
    k %= a.length;
    reverse(a, 0, a.length - 1);
    reverse(a, 0, k - 1);
    reverse(a, k, a.length - 1);
}

static void reverse(int[] a, int i, int j) { while (i < j) swap(a, i++, j--); }

static int majority(int[] a) {                   // Boyer-Moore voting
    int cand = 0, count = 0;
    for (int x : a) {
        if (count == 0) cand = x;
        count += (x == cand) ? 1 : -1;
    }
    return cand;
}

static List<Integer> majorityThird(int[] a) {
    int c1 = 0, c2 = 1, n1 = 0, n2 = 0;
    for (int x : a) {
        if (x == c1) n1++;
        else if (x == c2) n2++;
        else if (n1 == 0) { c1 = x; n1 = 1; }
        else if (n2 == 0) { c2 = x; n2 = 1; }
        else { n1--; n2--; }
    }
    int k1 = 0, k2 = 0;
    for (int x : a) { if (x == c1) k1++; else if (x == c2) k2++; }
    List<Integer> res = new ArrayList<>();
    if (k1 > a.length / 3) res.add(c1);
    if (k2 > a.length / 3) res.add(c2);
    return res;
}

static int maxProduct(int[] a) {
    int mx = a[0], mn = a[0], best = a[0];
    for (int i = 1; i < a.length; i++) {
        int x = a[i];
        int hi = Math.max(x, Math.max(mx * x, mn * x));
        int lo = Math.min(x, Math.min(mx * x, mn * x));
        mx = hi; mn = lo;
        best = Math.max(best, mx);
    }
    return best;
}

